        self.channels = [PWMOutputDevice(channel, active_high=False, initial_value=0) for channel in channels]
        self.adc = MCP3008(channel=adc_channel)
        self.running = True

    def read_adc(self):
        try:
            value = self.adc.value
            if 0 <= value <= 1:
                return value
            else:
                print(f"ADC read {value} is invalid.")
                return None
        except Exception as e:
            print(f"Failed to read ADC: {e}")
            return None

    def update_pwm(self):
        value = self.read_adc()
        if value is not None:
            for channel in self.channels:
                channel.duty_cycle = value

    def run(self):
        while self.running:
            self.update_pwm()
            time.sleep(0.1)

    def stop(self):
        self.running = False
        for channel in self.channels:
            channel.close()

