from paho.mqtt.client import Client

class Camera:
    def __init__(self):
        self.picam2 = picamera2.Picamera2()
        self.button = Button(2)
        self.mqtt = MQTT(Client())

    def capture_image(self):
        try:
            self.picam2.start()
            self.picam2.capture_file("/home/pi/image.jpg")
        except Exception as e:
            print(f"Capture failed: {e}")
            return False
        else:
            return True

    def publish_mqtt(self, image_data):
        try:
            self.mqtt.connect("mqtt.eclipse.org", 1883, 60)
            self.mqtt.publish("raspberrypi/image", image_data)
        except Exception as e:
            print(f"MQTT publish failed: {e}")

    def run(self):
        signal.signal(signal.SIGINT, self.exit_gracefully)
        while not self.button.is_pressed:
            if self.capture_image():
                with open("/home/pi/image.jpg", "rb") as file:
                    image_data = file.read()
                self.publish_mqtt(image_data)
            time.sleep(2)
        self.exit_gracefully(None, None)

    def exit_gracefully(self, signum, frame):
        try:
            self.picam2.stop()
            self.mqtt.disconnect()
        except Exception as e:
            print(f"Error while stopping camera and disconnecting MQTT: {e}")
        finally:
            print("Exiting...")
            exit(0)

