        self.picam2.stop()
        self.mqtt_client.disconnect()

    def run(self):
        signal.signal(signal.SIGINT, self.stop)
        signal.signal(signal.SIGTERM, self.stop)

        if not self.capture_image():
            return
        if not self.check_image():
            return
        if not self.publish_image():
