class UltrasonicSensor:
    def __init__(self, trigger_pin, echo_pin, timeout=0.1):
        self.trigger = gpiozero.OutputDevice(trigger_pin)
        self.echo = gpiozero.InputDevice(echo_pin, timeout=timeout)

    def __enter__(self):
        self.trigger.on()
        time.sleep(0.001)
        self.trigger.off()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.trigger.close()
        self.echo.close()

    def get_distance(self):
        with self:
            start = time.time()
            while self.echo.value == 0:
                if self.echo.timed_out:
                    raise RuntimeError('No echo received')
                time.sleep(0.00001)
            while self.echo.value == 1:
                if self.echo.timed_out:
                    break
                time.sleep(0.00001)
            end = time.time()
        return (end - start) * 340.29 / 2

