class SensorInterrupt(Exception):
    pass

class UltrasonicSensor:
    def __init__(self, trigger_pin, echo_pin, timeout=0.01):
        self.trigger = gpiozero.OutputDevice(trigger_pin)
        self.echo = gpiozero.InputDevice(echo_pin)
        self.timeout = timeout

    def __enter__(self):
        self.trigger.on()
        time.sleep(0.001)
        self.trigger.off()
        start = time.time()
        while not self.echo.is_active:
            if time.time() - start > self.timeout:
                raise SensorInterrupt("Sensor did not respond")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.trigger.close()
        self.echo.close()

    def get_distance(self):
        start = time.time()
        while self.echo.is_active:
            if time.time() - start > self.timeout:
                raise SensorInterrupt("Sensor did not respond")
        return time.time() - start

