import smbus2
from gpiozero import I2C

class BME280:
    def __init__(self, bus=1, addr=0x76):
        self.bus = smbus2.SMBus(bus)
        self.addr = addr

    def read(self):
        try:
            data = self.bus.read_i2c_block_data(self.addr, 0xF7, 8)
            temperature = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            pressure = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
            humidity = (data[6] << 8) | data[7]

            # Check validity of readings
            if temperature < 20000 or temperature > 85000 or pressure < 2000 or pressure > 11000 or humidity < 0 or humidity > 1000:
                print("Invalid reading, discarding")
                return None

            return {"temperature": temperature / 100.0, "pressure": pressure / 100.0, "humidity": humidity / 1000.0}
        except Exception as e:
            print(f"Error reading from BME280: {e}")
            return None

    def close(self):
        self.bus.close()


if __name__ == "__main__":
    try:
        sensor = BME280()
        reading = sensor.read()
        if reading is not None:
            print(reading)
    except Exception as e:
        print(f"Error: {e}")
    finally:
        sensor.close()

